package org.audiveris.omr.score;
import java.nio.file.*;import java.util.*;import java.awt.Rectangle;import org.audiveris.omr.sheet.Book;import org.audiveris.omr.sig.inter.*;
public class SourceCurvedRest400 {
 static String sha(Path p)throws Exception{return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(p)));}
 static String symbol(int u,int sys,Inter n){return u+"/"+sys+"/"+n.getId()+"/"+n.getShape()+"/"+n.getBounds()+"/"+(n.getGlyph()==null?"null":n.getGlyph().getId())+"/"+((AbstractPitchedInter)n).getPitch();}
 static Set<String> physical(Book book){var result=new TreeSet<String>();for(var st:book.getStubs())for(var sy:st.getSheet().getSystems())for(var n:sy.getSig().vertexSet())if(n instanceof HeadInter||n instanceof RestInter)result.add(symbol(st.getNumber(),sy.getId(),n));return result;}
 static void require(boolean b,String s){if(!b)throw new IllegalArgumentException(s);}
 public static void main(String[] a)throws Exception{((ch.qos.logback.classic.Logger)org.slf4j.LoggerFactory.getLogger(org.slf4j.Logger.ROOT_LOGGER_NAME)).setLevel(ch.qos.logback.classic.Level.WARN);Path input=Path.of(a[0]),source=Path.of(a[2]),out=Path.of(a[4]);require(sha(input).equals(a[1]),"source book SHA changed");Files.createDirectory(out);SourceStructure335.source=source;var book=Book.loadBook(input);var expected=physical(book);var targets=new ArrayList<RestInter>();var measures=new LinkedHashSet<org.audiveris.omr.sheet.rhythm.Measure>();var seen=new HashSet<String>();var decisions=new ArrayList<String>();decisions.add("unit\tsystem\trest\tmode\tstate");
 for(String line:Files.readAllLines(Path.of(a[3]))){if(line.isBlank())continue;var f=line.split("\\t");require(f.length==8&&seen.add(f[0]+"/"+f[1]+"/"+f[2]),"invalid or duplicate rest proof");int unit=Integer.parseInt(f[0]),sysid=Integer.parseInt(f[1]),id=Integer.parseInt(f[2]);var sys=book.getStub(unit).getSheet().getSystems().stream().filter(v->v.getId()==sysid).findFirst().orElseThrow();var n=sys.getSig().vertexSet().stream().filter(v->v.getId()==id).findFirst().orElseThrow();require(n instanceof RestInter&&n.getShape()==org.audiveris.omr.glyph.Shape.HALF_REST,"source target not half rest");require(n.getGlyph()!=null&&n.getGlyph().getId()==Integer.parseInt(f[3])&&n.getBounds().equals(new Rectangle(Integer.parseInt(f[4]),Integer.parseInt(f[5]),Integer.parseInt(f[6]),Integer.parseInt(f[7]))),"source rest identity changed");var rest=(RestInter)n;var chord=rest.getChord();require(chord!=null&&chord.getNotes().size()==1&&chord.getMeasure()!=null,"ambiguous source rest chord");targets.add(rest);measures.add(chord.getMeasure());if(a[5].equals("apply"))require(expected.remove(symbol(unit,sysid,n)),"source rest not in physical inventory");decisions.add(String.join("\t",f[0],f[1],f[2],a[5],a[5].equals("apply")?"retired_paired_source_arc":"control_preserved"));}
 if(a[5].equals("apply"))for(var rest:targets){var chord=rest.getChord();rest.remove();if(!chord.isRemoved())chord.remove();}
 var rhythms=new ArrayList<String>();rhythms.add("unit\tsystem\tnative_stack\texpected\tslots_duration");var stacks=new LinkedHashSet<org.audiveris.omr.sheet.rhythm.MeasureStack>();for(var m:measures)stacks.add(m.getStack());for(var stack:stacks){var duration=stack.getExpectedDuration();require(duration!=null,"source expected duration missing");for(var m:stack.getMeasures())m.resetRhythm();stack.resetRhythm();new org.audiveris.omr.sheet.rhythm.StackRhythm(stack).process(duration);rhythms.add(stack.getSystem().getSheet().getStub().getNumber()+"\t"+stack.getSystem().getId()+"\t"+stack.getPageId()+"\t"+duration+"\t"+stack.getSlotsDuration());stack.getSystem().getSheet().getStub().setModified(true);}require(physical(book).equals(expected),"unexpected real head/rest/pitch changes");book.setModified(true);book.store(out.resolve("refined.omr"),false);book.setExportPathSansExt(out.resolve("result"));require(book.export(book.getValidStubs(),book.getScores()),"native curve-rest export failed");SourceStructure335.writeLedgers(out);Files.write(out.resolve("decisions.tsv"),decisions);Files.write(out.resolve("measure-rhythm.tsv"),rhythms);require(sha(input).equals(a[1]),"original source book mutated");System.out.println("SOURCE_PAIRED_CURVED_RESTS "+a[5]+" "+targets.size());System.exit(0);}
}
